import React, { useState } from "react";
import { Form, FormGroup, Label, Input, Row, Col, Button } from "reactstrap";
import "../Styles/Userregister.css";

const INDUSTRIES = [
  "Technology",
  "Education",
  "Hospitality / Coffee Shop",
  "Retail / Store",
  "Logistics",
  "Government Services",
  "Other",
];

const CompanyRegister = () => {
  const [companyName, setCompanyName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [entityType, setEntityType] = useState("Private"); // Radio ✅
  const [industry, setIndustry] = useState(INDUSTRIES[0]); // Dropdown ✅
  const [address, setAddress] = useState("");
  const [training, setTraining] = useState(false); // Checkbox ✅
  const [founded, setFounded] = useState(""); // Date Picker ✅
  const [password, setPassword] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    const payload = {
      companyName,
      email,
      phone,
      entityType,
      industry,
      address,
      trainingAvailable: training,
      founded,
      password,
    };
    console.log("COMPANY REGISTER (mock):", payload);
    alert("Company registered (mock) ✅");
  };

  return (
    <div className="register-page">
      <h1 className="register-title">
        Create your <span className="accent">account</span>
      </h1>

      <p className="register-sub">
        Please choose your role to continue and fill in the following:
      </p>

      {/* SAME SWITCH STYLE AS STUDENT ✅ */}
      <div className="role-switch">
        <button className="role-btn">Student</button>
        <button className="role-btn active">Company</button>
      </div>

      {/* CARD SAME STYLE AS STUDENT CARD ✅ */}
      <div className="register-card">
        <Form onSubmit={handleSubmit}>
          <FormGroup>
            <Label>Company Name</Label>
            <Input
              type="text"
              placeholder="Dhofar Advertising Co."
              value={companyName}
              onChange={(e) => setCompanyName(e.target.value)}
              required
            />
          </FormGroup>

          <Row>
            <Col md={6}>
              <FormGroup>
                <Label>Email</Label>
                <Input
                  type="email"
                  placeholder="hr@company.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
            <Col md={6}>
              <FormGroup>
                <Label>Phone</Label>
                <Input
                  type="tel"
                  placeholder="+968 9xx xxx xx"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  required
                />
              </FormGroup>
            </Col>
          </Row>

          <Label className="small-label">Entity Type</Label>
          <div className="radio-group">
            <label>
              <Input
                type="radio"
                value="Private"
                checked={entityType === "Private"}
                onChange={(e) => setEntityType(e.target.value)}
              />{" "}
              Private
            </label>
            <label>
              <Input
                type="radio"
                value="Government"
                checked={entityType === "Government"}
                onChange={(e) => setEntityType(e.target.value)}
              />{" "}
              Government / Ministry
            </label>
            <label>
              <Input
                type="radio"
                value="SmallBusiness"
                checked={entityType === "SmallBusiness"}
                onChange={(e) => setEntityType(e.target.value)}
              />{" "}
              Small Business
            </label>
          </div>

          <FormGroup>
            <Label>Industry</Label>
            <Input
              type="select"
              value={industry}
              onChange={(e) => setIndustry(e.target.value)}
            >
              {INDUSTRIES.map((i) => (
                <option key={i}>{i}</option>
              ))}
            </Input>
          </FormGroup>

          <FormGroup>
            <Label>Business Address</Label>
            <Input
              type="text"
              placeholder="Salalah, Saada …"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
            />
          </FormGroup>

          <FormGroup check className="checkbox-row">
            <Input
              type="checkbox"
              checked={training}
              onChange={(e) => setTraining(e.target.checked)}
            />
            <Label check>We provide training for newcomers</Label>
          </FormGroup>

          <FormGroup>
            <Label>Founded Date</Label>
            <Input
              type="date"
              value={founded}
              onChange={(e) => setFounded(e.target.value)}
            />
          </FormGroup>

          <FormGroup>
            <Label>Password</Label>
            <Input
              type="password"
              placeholder="********"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </FormGroup>

          <button type="submit" className="register-btn">
            Sign up
          </button>

          <p className="login-switch">
            Already have an account? <span>Log in now!</span>
          </p>
        </Form>
      </div>
    </div>
  );
};

export default CompanyRegister;
